    - name: Run pi-action
      id: run-pi-action
      shell: bash
      run: node --disable-warning=ExperimentalWarning ${{ github.action_path }}/src/index.ts
      env:
        INPUT_GITHUB_TOKEN: ${{ inputs.github_token }}
        INPUT_API_KEY: ${{ inputs.api_key }}
        INPUT_TRIGGER_PHRASE: ${{ inputs.trigger_phrase }}
        INPUT_ALLOWED_BOTS: ${{ inputs.allowed_bots }}
        INPUT_ALLOWED_USERS: ${{ inputs.allowed_users }}
        INPUT_ALLOWED_ASSOCIATIONS: ${{ inputs.allowed_associations }}
        INPUT_TIMEOUT: ${{ inputs.timeout }}
        INPUT_POLL_INTERVAL: ${{ inputs.poll_interval }}
        INPUT_PROVIDER: ${{ inputs.provider }}
        INPUT_MODEL: ${{ inputs.model }}
        INPUT_PROVIDER_BASE_URL: ${{ inputs.provider_base_url }}
        INPUT_PROVIDER_API: ${{ inputs.provider_api }}
        INPUT_PROVIDER_API_KEY: ${{ inputs.provider_api_key }}
        INPUT_PROVIDER_AUTH_HEADER: ${{ inputs.provider_auth_header }}
        INPUT_MODEL_NAME: ${{ inputs.model_name }}
        INPUT_MODEL_REASONING: ${{ inputs.model_reasoning }}
        INPUT_MODEL_INPUT: ${{ inputs.model_input }}
        INPUT_MODEL_CONTEXT_WINDOW: ${{ inputs.model_context_window }}
        INPUT_MODEL_MAX_TOKENS: ${{ inputs.model_max_tokens }}
        INPUT_COMPAT_SUPPORTS_DEVELOPER_ROLE: ${{ inputs.compat_supports_developer_role }}
        INPUT_COMPAT_SUPPORTS_REASONING_EFFORT: ${{ inputs.compat_supports_reasoning_effort }}
        INPUT_COMPAT_FORCE_ADAPTIVE_THINKING: ${{ inputs.compat_force_adaptive_thinking }}
        INPUT_EXTENSIONS: ${{ inputs.extensions }}
        INPUT_TRUST_PROJECT: ${{ inputs.trust_project }}
        INPUT_AGENT_DIR: ${{ inputs.agent_dir }}
        INPUT_WORKTREE_SNAPSHOTS: ${{ inputs.worktree_snapshots }}
        INPUT_WORKTREE_SNAPSHOT_EXCLUDE: ${{ inputs.worktree_snapshot_exclude }}
        INPUT_PROMPT_TEMPLATE: ${{ inputs.prompt_template }}
        INPUT_OUTPUT_MODE: ${{ inputs.output_mode }}
        INPUT_PROMPT: ${{ inputs.prompt }}
        INPUT_PR_NUMBER: ${{ inputs.pr_number }}

    # Pushes the thread's refs/pi/threads/<number> (and refs/pi/worktrees/<number>) if the step above was cancelled,
    # timed out, or crashed before its own final push. Fast-forward only: it never overwrites another run's history.
    - name: Save pi thread state
      if: always()
      shell: bash
      run: node --disable-warning=ExperimentalWarning ${{ github.action_path }}/src/push.ts
      env:
        INPUT_PR_NUMBER: ${{ inputs.pr_number }}
# Notes for agents

Read [CONTRIBUTING.md](CONTRIBUTING.md) before you change this repository. In particular:

- **Commits.** Use Conventional Commits, as in [Commit messages](CONTRIBUTING.md#commit-messages). The `commitlint` job in [`ci.yml`](.github/workflows/ci.yml) checks every commit of a pull request with [`commitlint.config.js`](commitlint.config.js). `git commit --no-verify` does not skip it.
- **Checks.** Run `npm run check` before you push. CI runs the same command.
- **Docs.** Update the documentation when you change behavior. Follow the [documentation style](CONTRIBUTING.md#documentation-style).
// Reading the action's inputs (see action.yml) into ActionInputs. Empty or invalid values fall back to DEFAULTS.
import type {
	CustomProviderConfig,
	ModelInputMode,
} from "./custom-provider.ts";
import { DEFAULTS } from "./defaults.ts";
import {
	DEFAULT_SNAPSHOT_LIMITS,
	type SnapshotLimits,
} from "./storage/worktree.ts";

export type InputReader = (name: string) => string;

export interface ActionInputs {
	triggerPhrase: string;
	allowedBots: string[];
	allowedUsers: string[];
	allowedAssociations: string[];
	provider: string;
	model: string;
	/** Seconds before the run is aborted. */
	timeout: number;
	githubToken: string | undefined;
	/** The provider's key, kept in memory for this run only. */
	apiKey: string | undefined;
	customProvider: CustomProviderConfig | undefined;
	promptTemplate: string | undefined;
	outputMode: "comment" | "output";
	prompt: string | undefined;
	prNumber: number | undefined;
	/** Seconds between checks for new comments while pi works. */
	pollInterval: number;
	/** pi extensions to load (npm specs or workspace paths) for the providers they register. */
	extensions: string[];
	/** Whether pi-durable extensions may load and run the repository's own configuration (`trust_project`). */
	trustProject: boolean;
	/** The agent directory for pi-durable extensions; a temp dir when unset. */
	agentDir: string | undefined;
	/** Whether a thread saves and restores the files pi left uncommitted (`worktree_snapshots`). */
	worktreeSnapshots: boolean;
	/** What a snapshot leaves out of the untracked files. */
	worktreeLimits: SnapshotLimits;
}

const TRUE_VALUES = new Set(["true", "1", "yes", "y", "on"]);
const FALSE_VALUES = new Set(["false", "0", "no", "n", "off"]);
const MODEL_INPUT_MODES: ReadonlySet<string> = new Set<ModelInputMode>([
	"text",
	"image",
]);
const INTEGER_PATTERN = /^\d+$/u;
const LINE_BREAK = /\r?\n/u;
/** A `#` at the start of a line or after whitespace starts a comment; `github:owner/repo#ref` keeps its `#`. */
const EXTENSION_COMMENT = /(?:^|\s)#.*$/u;
const COMPAT_INPUTS = {
	supportsDeveloperRole: "compat_supports_developer_role",
	supportsReasoningEffort: "compat_supports_reasoning_effort",
	forceAdaptiveThinking: "compat_force_adaptive_thinking",
} as const;

export function parseCsv(value: string): string[] {
	return value
		.split(",")
		.map((entry) => entry.trim())
		.filter(Boolean);
}

/**
 * pi extension specs, newline- or comma-separated. Blank lines are skipped, and so are `#` comments: whole lines, or
 * the rest of a line after a spec (`pkg@1.2.3  # why`). Comments are removed before the commas split the line.
 */
export function parseExtensionSpecs(value: string): string[] {
	return value
		.split(LINE_BREAK)
		.flatMap((line) => line.replace(EXTENSION_COMMENT, "").split(","))
		.map((spec) => spec.trim())
		.filter((spec) => spec !== "" && !spec.startsWith("#"));
}

/** true/1/yes/y/on or false/0/no/n/off, in any case; undefined for anything else. */
export function parseBoolean(value: string): boolean | undefined {
	const normalized = value.trim().toLowerCase();
	if (TRUE_VALUES.has(normalized)) {
		return true;
	}
	return FALSE_VALUES.has(normalized) ? false : undefined;
}

export function parsePositiveInteger(value: string): number | undefined {
	const normalized = value.trim();
	const parsed = INTEGER_PATTERN.test(normalized)
		? Number.parseInt(normalized, 10)
		: 0;
	return parsed > 0 ? parsed : undefined;
}

function parseModelInputModes(value: string): ModelInputMode[] {
	const modes = parseCsv(value).filter((mode): mode is ModelInputMode =>
		MODEL_INPUT_MODES.has(mode),
	);
	return modes.length > 0 ? modes : [DEFAULTS.customModelInput];
}

function readCompat(readInput: InputReader): CustomProviderConfig["compat"] {
	const compat = Object.fromEntries(
		Object.entries(COMPAT_INPUTS).flatMap(([key, name]) => {
			const value = parseBoolean(readInput(name));
			return value === undefined ? [] : [[key, value]];
		}),
	);
	return Object.keys(compat).length > 0 ? compat : undefined;
}

/** The single custom provider/model from the flat provider_* and model_* inputs; undefined without a base URL. */
export function readCustomProviderConfig(
	readInput: InputReader,
): CustomProviderConfig | undefined {
	const baseUrl = readInput("provider_base_url").trim();
	if (!baseUrl) {
		return undefined;
	}
	const apiKey = readInput("provider_api_key").trim();
	const modelName = readInput("model_name").trim();
	const compat = readCompat(readInput);
	return {
		baseUrl,
		api: readInput("provider_api") || DEFAULTS.customProviderApi,
		...(apiKey ? { apiKey } : {}),
		authHeader:
			parseBoolean(readInput("provider_auth_header")) ??
			DEFAULTS.customProviderAuthHeader,
		...(modelName ? { modelName } : {}),
		reasoning:
			parseBoolean(readInput("model_reasoning")) ??
			DEFAULTS.customModelReasoning,
		input: parseModelInputModes(readInput("model_input")),
		contextWindow:
			parsePositiveInteger(readInput("model_context_window")) ??
			DEFAULTS.customModelContextWindow,
		maxTokens:
			parsePositiveInteger(readInput("model_max_tokens")) ??
			DEFAULTS.customModelMaxTokens,
		...(compat ? { compat } : {}),
	};
}

export function readActionInputs(
	readInput: InputReader,
	env: Record<string, string | undefined> = process.env,
): ActionInputs {
	return {
		triggerPhrase: readInput("trigger_phrase") || DEFAULTS.triggerPhrase,
		allowedBots: parseCsv(readInput("allowed_bots")),
		allowedUsers: parseCsv(readInput("allowed_users")),
		allowedAssociations: parseCsv(
			readInput("allowed_associations") ||
				DEFAULTS.allowedAssociations.join(","),
		),
		provider: readInput("provider") || DEFAULTS.provider,
		model: readInput("model") || DEFAULTS.model,
		timeout: parsePositiveInteger(readInput("timeout")) ?? DEFAULTS.timeout,
		githubToken: readInput("github_token") || env["GITHUB_TOKEN"],
		apiKey: readInput("api_key") || undefined,
		customProvider: readCustomProviderConfig(readInput),
		promptTemplate: readInput("prompt_template") || undefined,
		outputMode:
			readInput("output_mode") === "output" ? "output" : DEFAULTS.outputMode,
		prompt: readInput("prompt") || undefined,
		prNumber: parsePositiveInteger(readInput("pr_number")),
		pollInterval:
			parsePositiveInteger(readInput("poll_interval")) ?? DEFAULTS.pollInterval,
		extensions: parseExtensionSpecs(readInput("extensions")),
		trustProject:
			parseBoolean(readInput("trust_project")) ?? DEFAULTS.trustProject,
		agentDir: readInput("agent_dir").trim() || undefined,
		worktreeSnapshots:
			parseBoolean(readInput("worktree_snapshots")) ??
			DEFAULTS.worktreeSnapshots,
		worktreeLimits: {
			...DEFAULT_SNAPSHOT_LIMITS,
			exclude: parseExtensionSpecs(readInput("worktree_snapshot_exclude")),
		},
	};
}
/** The logging that every part of a run needs. */
export interface Log {
	info: (msg: string) => void;
	warning: (msg: string) => void;
	/** Plumbing (each push, each snapshot), shown with step debug logging; `info` when absent. */
	debug?: ((msg: string) => void) | undefined;
}

/** A question a pi-durable extension asks its user; `key` is stable for the same question (pit derives it). */
export type UiQuestion =
	| { kind: "confirm"; key: string; title: string; message: string }
	| { kind: "select"; key: string; title: string; options: string[] }
	| { kind: "input"; key: string; title: string; placeholder?: string };

/** Someone's answer to a question, delivered to the thread as a `ui.answer` entry. */
export interface UiAnswer {
	key: string;
	kind: UiQuestion["kind"];
	/** `true`/`false` for confirm, the option for select, the text for input. */
	answer: boolean | string;
	/** Who answered (a GitHub login). */
	by: string;
	/** The question's comment. */
	url: string;
	title: string;
}

/**
 * The UI pi-action gives pi-durable extensions: an asynchronous host (the interface `pit/durable` defines). `ask`
 * posts the question on the issue or PR and returns at once; the answer arrives in a later run as a `ui.answer` entry
 * (see github-ui.ts and answers.ts).
 */
export interface DurableUi {
	ask: (question: UiQuestion) => Promise<{ url?: string }>;
	notify: (message: string, level?: "info" | "warning" | "error") => void;
}

/** What a pi-durable extension package's `createPiDurableExtension(options)` receives from pi-action. */
export interface DurableHostOptions {
	/** The workspace (the checked-out repository). */
	cwd: string;
	/** The extension's agent directory (user-level state): the `agent_dir` input, else a temp dir. */
	agentDir: string;
	/** The `trust_project` input: whether the extension may load and run the repository's own configuration. */
	trustProject: boolean;
	/** GitHub comments as dialogs; omitted in output mode and for direct prompts. */
	ui?: DurableUi;
	log: Log;
}

export type GitHubReaction =
	| "+1"
	| "-1"
	| "laugh"
	| "confused"
	| "heart"
	| "hooray"
	| "rocket"
	| "eyes";

export interface GitHubUser {
	login: string;
	type: "User" | "Bot" | "Organization";
}

/**
 * Repository reference with clearer naming (avoids repo.repo)
 */
export interface RepoRef {
	owner: string;
	name: string;
}

/** Where a trigger came from: an issue/PR body, an issue comment, or a PR review comment. */
export type TriggerSource = "body" | "comment" | "review_comment";

/** The issue, PR, or comment of the webhook event that started the run. */
export interface TriggerInfo {
	triggerText: string;
	author: GitHubUser;
	authorAssociation: string;
	issueNumber: number;
	issueTitle: string;
	issueBody: string;
	commentId?: number;
	isPullRequest: boolean;
	source: TriggerSource;
	createdAt?: string;
	url?: string;
}

/** An issue or review comment as listed by the REST API. */
export interface GitHubComment {
	id: number;
	body?: string | null;
	user?: { login: string; type: string } | null;
	author_association: string;
	created_at: string;
	html_url: string;
	path?: string | null;
	line?: number | null;
}

type Params<T> = { owner: string; repo: string; [key: string]: unknown } & T;

interface ListParams {
	since?: string;
	per_page?: number;
	page?: number;
}

/** The fields of Octokit's pull request object that pi-action reads. */
interface OctokitPullRequest {
	number: number;
	title: string;
	body: string | null;
}

/** The part of Octokit that pi-action uses. */
export interface OctokitClient {
	rest: {
		reactions: {
			createForIssueComment: (
				params: Params<{ comment_id: number; content: GitHubReaction }>,
			) => Promise<unknown>;
			createForPullRequestReviewComment: (
				params: Params<{ comment_id: number; content: GitHubReaction }>,
			) => Promise<unknown>;
			createForIssue: (
				params: Params<{ issue_number: number; content: GitHubReaction }>,
			) => Promise<unknown>;
		};
		issues: {
			createComment: (
				params: Params<{ issue_number: number; body: string }>,
			) => Promise<{ data: { id: number; html_url: string } }>;
			listComments: (
				params: Params<{ issue_number: number } & ListParams>,
			) => Promise<{ data: GitHubComment[] }>;
			getComment: (
				params: Params<{ comment_id: number }>,
			) => Promise<{ data: GitHubComment }>;
			updateComment: (
				params: Params<{ comment_id: number; body: string }>,
			) => Promise<unknown>;
		};
		repos: {
			getCollaboratorPermissionLevel: (
				params: Params<{ username: string }>,
			) => Promise<{ data: { permission: string; role_name?: string } }>;
		};
		pulls: {
			get: (
				params: Params<{
					pull_number: number;
					mediaType?: { format: string };
				}>,
			) => Promise<{ data: OctokitPullRequest }>;
			listReviewComments: (
				params: Params<{ pull_number: number } & ListParams>,
			) => Promise<{ data: GitHubComment[] }>;
		};
	};
}
